// The name foldings against the contract's `name_folding` vectors (inbox #350, ADR 0080). Both foldings are frozen into
// every stored slug token (`slug_token` HMACs their output), so their outputs are conformance truth, not unit-test
// taste: the vectors were generated by an independent Python implementation, and these assertions are what holds the
// TS functions to them. A changed rule in either function turns a case here red.
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileNameSlug, slugify } from './naming'

type Case = { name: string; slug: string; exercises: string }
const vectors = JSON.parse(
  readFileSync(resolve(__dirname, '../../../../contracts/crypto/vectors/v1.json'), 'utf8'),
) as { name_folding: { slugify: Case[]; fileNameSlug: Case[] } }
const V = vectors.name_folding
const slugOf = (cases: Case[], name: string) => {
  const c = cases.find((x) => x.name === name)
  if (!c) throw new Error(`no vector for ${JSON.stringify(name)}`)
  return c.slug
}

describe('name_folding vectors', () => {
  it.each(V.slugify.map((c) => [c.exercises, c] as const))('slugify: %s', (_, c) => {
    expect(slugify(c.name)).toBe(c.slug)
  })

  it.each(V.fileNameSlug.map((c) => [c.exercises, c] as const))('fileNameSlug: %s', (_, c) => {
    expect(fileNameSlug(c.name)).toBe(c.slug)
  })

  // The owner's decided collisions, read off the vectors themselves, so a regenerated vector file that quietly
  // reverses one fails here and not only in review.
  it('containers: Müller collides with Mueller and Day1.md with Day1 md', () => {
    expect(slugOf(V.slugify, 'Müller')).toBe(slugOf(V.slugify, 'Mueller'))
    expect(slugOf(V.slugify, 'Day1.md')).toBe(slugOf(V.slugify, 'Day1 md'))
  })

  it('containers: a decomposed and a composed spelling are one name (inbox #365)', () => {
    expect(slugOf(V.slugify, 'Müller')).toBe(slugOf(V.slugify, 'Müller'))
    expect(slugOf(V.slugify, '한')).toBe(slugOf(V.slugify, '한'))
  })

  it('files: case collides, punctuation does not, composed and decomposed ä are one name', () => {
    expect(slugOf(V.fileNameSlug, 'Foto.JPG')).toBe(slugOf(V.fileNameSlug, 'foto.jpg'))
    expect(slugOf(V.fileNameSlug, 'README')).toBe(slugOf(V.fileNameSlug, 'readme'))
    expect(slugOf(V.fileNameSlug, 'Day1.md')).not.toBe(slugOf(V.fileNameSlug, 'Day1 md'))
    expect(slugOf(V.fileNameSlug, 'Käse.txt')).toBe(slugOf(V.fileNameSlug, 'Käse.txt'))
  })
})
